(function(){
const pageTitles={home:"Home",converter:"Model Converter",density:"Density Tuner"};
const pages=document.querySelectorAll(".page");
const navItems=document.querySelectorAll(".nav-item[data-page]");
function openPage(name){pages.forEach(p=>p.classList.toggle("active",p.id==="page-"+name));navItems.forEach(n=>n.classList.toggle("active",n.dataset.page===name));document.getElementById("page-title").textContent=pageTitles[name]||"CAE Engineering Toolbox";}
navItems.forEach(btn=>btn.addEventListener("click",()=>openPage(btn.dataset.page)));
document.querySelectorAll("[data-open]").forEach(card=>card.addEventListener("click",e=>{if(card.dataset.open!=="home"||e.target.tagName==="BUTTON")openPage(card.dataset.open);}));
function bridgeAvailable(){return !!(window.pywebview&&window.pywebview.api);}
window.addEventListener("pywebviewready",()=>{document.getElementById("runtime-label").textContent="pywebview Desktop";document.getElementById("runtime-detail").textContent="Python bridge connected";document.getElementById("bridge-status").textContent="Connected";document.getElementById("bridge-status").classList.add("ok");document.querySelector(".status-dot").style.background="#19a36a";document.getElementById("mode-pill").textContent="Desktop POC";});
const browserFileInput=document.getElementById("browser-model-input"),modelPath=document.getElementById("model-path"),fileMeta=document.getElementById("file-meta");
document.getElementById("browse-model").addEventListener("click",async()=>{if(bridgeAvailable()){try{const info=await window.pywebview.api.pick_model();if(info&&info.path){modelPath.value=info.path;modelPath.dataset.realPath=info.path;fileMeta.textContent=(info.name||"Model")+" · "+(info.size_kb||0)+" KB";}}catch(err){fileMeta.textContent="選檔失敗："+String(err);}}else browserFileInput.click();});
browserFileInput.addEventListener("change",()=>{const file=browserFileInput.files&&browserFileInput.files[0];if(!file)return;modelPath.value=file.name;modelPath.dataset.realPath="";fileMeta.textContent=file.name+" · "+Math.round(file.size/1024)+" KB · Browser preview only";});
document.getElementById("select-all-rules").addEventListener("click",()=>{const checks=[...document.querySelectorAll("[data-rule]")],allChecked=checks.every(x=>x.checked);checks.forEach(x=>x.checked=!allChecked);document.getElementById("select-all-rules").textContent=allChecked?"全選":"取消全選";});
function addLog(text,kind=""){const line=document.createElement("div");line.className="log-line "+kind;line.textContent=text;const box=document.getElementById("converter-log");box.appendChild(line);box.scrollTop=box.scrollHeight;}
document.getElementById("run-converter").addEventListener("click",async()=>{const selected=[...document.querySelectorAll("[data-rule]:checked")].map(x=>x.dataset.rule),displayPath=modelPath.value.trim(),state=document.getElementById("converter-state");document.getElementById("converter-log").innerHTML="";if(!displayPath){addLog("[ERROR] 請先選擇模型。","error");state.textContent="Missing input";return;}state.textContent="Dry Run";addLog("[START] Model Converter dry run","ok");addLog("[INPUT] "+displayPath);addLog("[RULES] "+selected.join(", "));if(bridgeAvailable()&&modelPath.dataset.realPath){try{const r=await window.pywebview.api.run_converter_dry_run(modelPath.dataset.realPath,selected);(r.log||[]).forEach(item=>addLog(item.text,item.kind));state.textContent=r.ok?"Ready":"Review";}catch(err){addLog("[ERROR] "+String(err),"error");state.textContent="Error";}}else{addLog("[INFO] 目前是 Browser preview，沒有 Python / HyperMesh bridge。","warn");addLog("[INFO] POC 只驗證 UI flow；不會假裝已完成 Material / Contact / Property 修復。","warn");addLog("[NEXT] 用 python desktop.py 開啟後，可測試 pywebview 選檔與 backend dry-run。","ok");state.textContent="Preview";}});
const unitToKg={ton:1000,kg:1,g:.001};
function parsePositive(v){const n=Number(String(v).trim());return Number.isFinite(n)&&n>0?n:null;}
function fmt(n){return n.toExponential(3).replace(/e\+?/,"E");}
function calculateDensity(){const density=parsePositive(document.getElementById("density-current").value),currentMass=parsePositive(document.getElementById("density-current-mass").value),targetMass=parsePositive(document.getElementById("density-target-mass").value),q=parsePositive(document.getElementById("density-quantity").value),currentUnit=document.getElementById("density-current-unit").value,targetUnit=document.getElementById("density-target-unit").value;if(density===null||currentMass===null||targetMass===null||q===null||!Number.isSafeInteger(q)){document.getElementById("density-result").textContent="Invalid input";return null;}const currentKg=currentMass*unitToKg[currentUnit],targetKg=targetMass*q*unitToKg[targetUnit],scale=targetKg/currentKg,newDensity=density*scale,expected=currentMass*(newDensity/density)*(unitToKg[currentUnit]/unitToKg[targetUnit]);document.getElementById("density-result").textContent=fmt(newDensity);document.getElementById("density-scale").textContent=scale.toFixed(5)+" ×";document.getElementById("density-expected").textContent=expected.toFixed(3)+" "+targetUnit;document.getElementById("density-total").textContent=(targetMass*q).toFixed(3)+" "+targetUnit;return{density:newDensity,expected,scale,targetUnit};}
document.getElementById("calculate-density").addEventListener("click",calculateDensity);["density-current","density-current-mass","density-target-mass","density-quantity","density-current-unit","density-target-unit"].forEach(id=>{document.getElementById(id).addEventListener("input",calculateDensity);document.getElementById(id).addEventListener("change",calculateDensity);});
document.getElementById("density-apply").addEventListener("click",async()=>{const result=calculateDensity(),status=document.getElementById("density-apply-status");if(!result){status.textContent="輸入數值無效，沒有產生 action plan。";return;}const target=document.getElementById("density-target-component").value.trim()||"(尚未指定 Component / Material)";if(bridgeAvailable()){try{const r=await window.pywebview.api.apply_density_dry_run(target,result.density);status.textContent=r.message;}catch(err){status.textContent="Dry Run 失敗："+String(err);}}else status.textContent="Browser preview：建議密度 "+fmt(result.density)+"；目標 "+target+"。未修改 HyperMesh。";});
document.getElementById("open-folder-btn").addEventListener("click",async()=>{if(bridgeAvailable()){try{await window.pywebview.api.open_project_folder();}catch(e){}}});
calculateDensity();
})();